CREATE DATABASE IF NOT EXISTS krx_etf_db DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE krx_etf_db;
CREATE TABLE IF NOT EXISTS etf_info (
 id BIGINT AUTO_INCREMENT PRIMARY KEY, base_date DATE NOT NULL, ticker VARCHAR(12) NOT NULL,
 etf_name VARCHAR(120) NOT NULL, closing_price BIGINT NOT NULL, price_change BIGINT NOT NULL,
 change_rate DECIMAL(8,2) NOT NULL, estimated_nav DECIMAL(18,2) NOT NULL,
 net_asset_total DECIMAL(22,2) NOT NULL, trading_volume BIGINT NOT NULL,
 trading_value BIGINT NOT NULL, underlying_index VARCHAR(150) NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
 ) ENGINE=InnoDB
 DEFAULT CHARACTER SET=utf8mb4
 COLLATE=utf8mb4_unicode_ci;

